INSERT INTO "app_settings" ("setting_key", "tenant_id", "setting_value")
VALUES ('faq', '148eb315-baf1-40d9-981f-6daee9653ac1', '{"fiyat":"Güncel fiyat bilgisi için lütfen yapmak istediğiniz işlemi belirtin.","konum":"Merkezimiz İstanbul''da yer almaktadır. (Buraya açık adresinizi yazın)","islemler":"Lazer epilasyon, cilt bakımı, bölgesel incelme ve protez tırnak hizmetlerimiz bulunmaktadır.","kampanya":"Şu anda tüm lazer paketlerinde %20 indirim kampanyamız bulunmaktadır.","aci_durumu":"Yeni nesil buz başlıklı lazer cihazlarımız sayesinde işlemlerimiz neredeyse ağrısız ve çok konforludur.","erkek_kabul":"Evet, erkek danışanlarımıza da hizmet vermekteyiz.","lazer_seans":"Lazer epilasyon genellikle 6-8 seans sürmektedir, ancak kıl yapısına göre uzmanlarımız tarafından belirlenmektedir.","calisma_saatleri":"Haftanın 7 günü 09:00 - 19:00 saatleri arasında hizmet vermekteyiz."}'::jsonb)
